const TICK=`<svg viewBox="0 0 24 24" fill="none" stroke="#F8FAF7" stroke-width="3.2" stroke-linecap="round" stroke-linejoin="round"><path d="M4 12.5l5.5 5.5L20 6.5"/></svg>`;

let lang="en", active=0, countTimer=null;
const t=k=>(I18N[lang]&&I18N[lang][k])||I18N.en[k]||k;
const reduced=window.matchMedia("(prefers-reduced-motion: reduce)").matches;

function applyLang(next){
  lang=I18N[next]?next:"en";
  document.documentElement.lang=lang;
  document.querySelectorAll("[data-i18n]").forEach(el=>{el.textContent=t(el.dataset.i18n)});
  document.querySelectorAll(".langpills button").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.lang===lang)));
  document.getElementById("langselect").value=lang;
  renderChips();
  renderTickets(false);
  if(window.splitText)window.splitText();
  if(window.renderTf)window.renderTf();
  if(window.renderStrip)window.renderStrip();
  if(window.resetGreeting)window.resetGreeting(lang);
  if(window.updateWx)window.updateWx();
}

function renderChips(){
  const box=document.getElementById("chips");
  box.innerHTML=BIZ.map((b,i)=>
    `<button type="button" class="chip" data-i="${i}" aria-pressed="${i===active}">${t("biz."+b.id)}</button>`).join("");
  box.querySelectorAll(".chip").forEach(c=>c.addEventListener("click",()=>{
    active=+c.dataset.i;
    box.querySelectorAll(".chip").forEach(x=>x.setAttribute("aria-pressed",String(+x.dataset.i===active)));
    renderTickets(true);
  }));
}

function renderTickets(animate){
  const biz=BIZ[active], box=document.getElementById("tickets");
  box.innerHTML=biz.tasks.map(([key,hrs],i)=>`
    <div class="ticket${animate&&!reduced?" anim-in":""}" style="animation-delay:${i*70}ms">
      <span class="ticket-tick">${TICK}</span>
      <span class="ticket-name">${t(key)}</span>
      <span class="ticket-hrs">${hrs.toFixed(1)} hr</span>
    </div>`).join("");
  const total=biz.tasks.reduce((a,[,h])=>a+h,0);
  countTo(total,animate);
  document.getElementById("monthline").textContent=t("card.month").replace("{n}",Math.round(total*4.33));
}

function countTo(target,animate){
  const el=document.getElementById("total");
  clearInterval(countTimer);
  if(!animate||reduced){el.textContent=target.toFixed(1);return;}
  const from=parseFloat(el.textContent)||0, start=performance.now(), dur=520;
  countTimer=setInterval(()=>{
    const p=Math.min(1,(performance.now()-start)/dur);
    el.textContent=(from+(target-from)*(1-Math.pow(1-p,3))).toFixed(1);
    if(p===1)clearInterval(countTimer);
  },16);
}

