/* drawer links: close the menu first, then scroll — otherwise the collapsing
   drawer shifts the page and the landing position is short by its height */
function headerOffset(){
  const h=document.querySelector("header");
  return (h?h.getBoundingClientRect().height:64)+14;
}
/* a slow, eased glide to any point on the page (menu links, What we do list). Any wheel, touch or key
   press from the visitor stops it at once, so it never fights them. */
window.ambsGlide=(function(){
  let raf=0;
  const calm=window.matchMedia&&matchMedia("(prefers-reduced-motion: reduce)").matches;
  const stop=()=>{if(raf){cancelAnimationFrame(raf);raf=0;}};
  ["wheel","touchstart","keydown","mousedown"].forEach(t=>addEventListener(t,stop,{passive:true}));
  return function(target){
    stop();target=Math.max(0,Math.min(target,document.documentElement.scrollHeight-innerHeight));
    const start=window.pageYOffset,dist=target-start;
    if(calm||Math.abs(dist)<2){window.scrollTo({top:target,behavior:"auto"});return;}
    const dur=Math.max(750,Math.min(1600,600+Math.abs(dist)*.16)),t0=performance.now();
    const ease=t=>t<.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;
    const step=now=>{const k=Math.min(1,(now-t0)/dur);window.scrollTo({top:start+dist*ease(k),behavior:"instant"});raf=k<1?requestAnimationFrame(step):0;};
    raf=requestAnimationFrame(step);
  };
})();
function scrollToId(id){
  const el=document.getElementById(id);if(!el)return;
  const y=el.getBoundingClientRect().top+window.pageYOffset-headerOffset();
  window.ambsGlide(Math.max(0,y));
  settleOn(id);
}
/* sections above can open up while the page glides past them (What we do on phones), so check on arrival and glide the last stretch */
let settleT=0;
function settleOn(id){
  clearTimeout(settleT);let stop=false,n=0,last=-1,ok=0;
  const quit=()=>{stop=true;};["wheel","touchstart","keydown"].forEach(ev=>addEventListener(ev,quit,{once:true,passive:true}));
  const tick=()=>{if(stop||n++>24)return;const el=document.getElementById(id);if(!el)return;
    const want=Math.max(0,Math.round(el.getBoundingClientRect().top+pageYOffset-headerOffset()));
    if(Math.abs(pageYOffset-last)<1){if(Math.abs(pageYOffset-want)>6){ok=0;window.ambsGlide(want);}else if(++ok>=2)return;}
    last=pageYOffset;settleT=setTimeout(tick,300);};
  settleT=setTimeout(tick,300);
}
dr.querySelectorAll("a").forEach(a=>a.addEventListener("click",e=>{
  const href=a.getAttribute("href")||"";
  dr.classList.remove("open");mb.setAttribute("aria-expanded","false");
  if(href.startsWith("#")&&href.length>1){
    e.preventDefault();
    const id=href.slice(1);
    /* wait for the drawer to finish collapsing, then measure and scroll */
    setTimeout(()=>scrollToId(id),430);
  }
}));
